(x, y, t) => {
const cx = 240, cy = 120;
  // Organic warp with energy flow
  const wx = Math.sin(x * 0.02 + t * 0.3) * 15 + Math.cos(y * 0.015 - t * 0.2) * 10 + Math.sin((x+y)*0.01 + t*0.5) * 8;
  const wy = Math.cos(y * 0.02 - t * 0.25) * 15 + Math.sin(x * 0.018 + t * 0.35) * 10 + Math.cos((x-y)*0.012 - t*0.4) * 8;
  const sx = x + wx, sy = y + wy;

  // Sources with gravitational orbital motion (energy conservation: potential↔kinetic)
  const src = [
    [160+Math.sin(t*0.6)*100, 80+Math.cos(t*0.4)*50, 0.08, 2.0],
    [320+Math.cos(t*0.5)*100, 160+Math.sin(t*0.7)*50, 0.1, 1.7],
    [240+Math.sin(t*0.3+2)*140, 120+Math.cos(t*0.5+1)*90, 0.06, 2.3],
    [120+Math.cos(t*0.8+1)*80, 180+Math.sin(t*0.6+3)*60, 0.12, 1.5],
    [360+Math.sin(t*0.4+4)*90, 60+Math.cos(t*0.9+2)*70, 0.07, 2.6],
    [240+Math.cos(t*0.35+5)*120, 200+Math.sin(t*0.55)*80, 0.09, 1.9]
  ];

  let aS = 0, iS = 0, potE = 0, kinE = 0;
  for (let si = 0; si < src.length; si++) {
    const [sX, sY, f, sp] = src[si];
    const d = Math.sqrt((sx-sX)**2 + (sy-sY)**2) + 0.1;
    aS += Math.sin(d*f - t*sp);
    iS += Math.sin(d*f*0.7 + t*sp*0.6 + 1.5);
    // Energy conservation: potential (1/d) + kinetic (v² ~ d_dot²)
    potE += 30 / d;
    kinE += Math.sin(d*f - t*sp)**2 * 2;
  }

  const act = aS/6, inh = iS/6;

  // Background with photosynthesis-inspired organic patterns
  const bg = (Math.sin(sx*0.04+sy*0.025+t*0.8) + Math.sin(sx*0.03-sy*0.04+t*1.1))/2 
    + Math.sin((sx+sy)*0.12+t*2.5)*0.2 + Math.sin((sx-sy)*0.1-t*2)*0.2
    + Math.sin(sx*0.07+Math.cos(sy*0.05+t)*3+t*0.6)*0.15; // organic vein pattern

  const dist = Math.sqrt((sx-cx)**2 + (sy-cy)**2), ang = Math.atan2(sy-cy, sx-cx);

  // Gravitational spiral
  const spiral = (Math.sin(dist*0.05-ang*3-t*1.5) + Math.sin(dist*0.04+ang*4-t*1.2))*0.4;

  // Orbital rings (gravity visualization)
  let orbit = 0;
  for (let r = 30; r < 180; r += 35) {
    const ring = Math.abs(dist - r - Math.sin(ang*3+t)*5);
    orbit += Math.max(0, 1 - ring/3) * (0.3 + 0.7 * Math.sin(t*0.5 + r*0.01)*0.5+0.5);
  }

  const reaction = Math.tanh((act - inh*0.7 + bg*0.3 + spiral)*2.2);

  // Energy ratio (conservation visualization)
  const totalE = potE + kinE + 0.01;
  const eRatio = kinE / totalE; // 0=potential, 1=kinetic

  const cell = Math.tanh((Math.sin(sx*0.15)*Math.sin(sy*0.15) + Math.sin((sx+sy)*0.1+t)*0.5)*1.5)*0.3;
  const blend = reaction*0.75 + cell*0.25 + orbit*0.15;
  const v = Math.max(0, Math.min(1, blend*0.5+0.5));

  // Neon palette: dark base → green (photosynthesis) → gold → hot pink → cyan
  const pal = [
    [5, 8, 25],      // deep dark blue-black
    [10, 40, 60],    // dark teal
    [0, 180, 100],   // neon green (photosynthesis)
    [80, 220, 60],   // bright green-gold
    [255, 200, 30],  // gold/yellow (energy)
    [255, 100, 60],  // hot orange
    [220, 50, 120],  // hot pink
    [120, 40, 200],  // purple
    [40, 180, 255],  // cyan
    [5, 8, 25]       // back to dark
  ];

  const idx = v*(pal.length-1);
  const i = Math.min(idx|0, pal.length-2);
  const f = idx-i;

  const lum = 0.8 + Math.sin(reaction*Math.PI)*0.2;
  const edge = Math.abs(reaction)>0.7 ? 1.3 : 1.0;
  const glow = orbit * 0.5;

  let r = (pal[i][0]+(pal[i+1][0]-pal[i][0])*f)*lum*edge + glow*40;
  let g = (pal[i][1]+(pal[i+1][1]-pal[i][1])*f)*lum*edge + glow*60;
  let b = (pal[i][2]+(pal[i+1][2]-pal[i][2])*f)*lum*edge + glow*80;

  // === UI OVERLAY ELEMENTS ===

  // Window frame
  const winL = 15, winR = 465, winT = 8, winB = 232;
  const borderW = 1.5;
  const onBorder = (x < winL+borderW || x > winR-borderW || y < winT+borderW || y > winB-borderW) ? 1 : 0;
  const insideWin = x > winL+borderW && x < winR-borderW && y > winT+borderW && y < winB-borderW;

  if (onBorder && insideWin === false) {
    const borderPulse = 0.7 + Math.sin(t*2)*0.3;
    return [(40*borderPulse)|0, (180*borderPulse)|0, (255*borderPulse)|0];
  }

  // Title bar
  if (y >= winT+borderW && y < winT+borderW+12 && insideWin) {
    const titleGrad = x / 480;
    return [(20+titleGrad*30)|0, (60+titleGrad*80)|0, (140+titleGrad*60)|0];
  }

  // Status bar at bottom
  if (y >= winB-borderW-10 && y < winB-borderW && insideWin) {
    const statusPulse = Math.sin(t*3 + x*0.05)*0.5+0.5;
    const barH = (y - (winB-borderW-10)) / 10;
    return [(10+barH*20+statusPulse*15)|0, (30+barH*40+statusPulse*30)|0, (60+barH*50+statusPulse*20)|0];
  }

  // Side panel
  if (x >= winL+borderW && x < winL+borderW+80 && y >= winT+borderW+14 && y < winB-borderW-12 && insideWin) {
    const panelX = (x - winL - borderW) / 80;
    const panelY = (y - winT - borderW - 14) / (winB - winT - 28);

    // Panel lines (text-like)
    const lineIdx = (panelY * 12)|0;
    const linePos = (panelY * 12) % 1;
    const isLine = linePos < 0.06 && lineIdx < 11;
    const isBar = linePos > 0.2 && linePos < 0.35 && lineIdx < 8;

    if (isLine) {
      const lineW = 0.3 + Math.sin(t*0.5 + lineIdx*1.7)*0.15 + eRatio*0.2;
      const onLine = panelX < lineW;
      if (onLine) return [(20+eRatio*60)|0, (80+eRatio*120)|0, (120-eRatio*40)|0];
    }
    if (isBar) {
      const barFill = (Math.sin(t*0.8 + lineIdx*2.1)*0.5+0.5) * (0.4 + eRatio*0.5);
      const onFill = panelX < barFill;
      const barBg = panelX < 1.0;
      if (barBg && !onFill) return [15, 35, 55];
      if (onFill) {
        const barColor = barFill > 0.7 ? [255, 80, 60] : barFill > 0.4 ? [255, 200, 30] : [0, 200, 120];
        return barColor;
      }
    }

    // Dim the panel background
    r *= 0.4; g *= 0.4; b *= 0.4;
    r += 8; g += 15; b += 25;
  }

  // Mini graph in bottom-right
  const gx = 380, gy = 170, gw = 75, gh = 45;
  if (x >= gx && x < gx+gw && y >= gy && y < gy+gh && insideWin) {
    const gpx = (x - gx) / gw, gpy = (y - gy) / gh;
    // Graph border
    if (gpx < 0.02 || gpx > 0.98 || gpy < 0.02 || gpy > 0.98) return [40, 120, 180];
    // Grid lines
    const gridH = Math.abs(gpy - 0.5) < 0.005 ? 1 : 0;
    const gridV = Math.abs(gpx - 0.5) < 0.005 ? 1 : 0;
    if (gridH || gridV) return [20, 50, 80];
    // Waveform
    const wave = Math.sin(gpx*8 - t*2)*0.3 + Math.sin(gpx*12 - t*3)*0.15 + Math.cos(gpx*5+t)*0.1;
    const onWave = Math.abs(gpy - 0.5 - wave) < 0.03;
    if (onWave) return [0, 255, 180];
    // Fill under wave
    if (gpy > 0.5 + wave && gpy < 0.98) return [0, 40, 30];
    return [5, 12, 25];
  }

  // Energy conservation indicator (top right)
  const ex = 350, ey = 25, ew = 100, eh = 6;
  if (x >= ex && x < ex+ew && y >= ey && y < ey+eh && insideWin) {
    const epx = (x - ex) / ew;
    const splitAt = eRatio;
    if (epx < splitAt) return [255, 200, 30]; // kinetic - gold
    return [30, 100, 200]; // potential - blue
  }

  // Apply final glow and clamp
  r = Math.min(255, r + glow * 30);
  g = Math.min(255, g + glow * 50);
  b = Math.min(255, b + glow * 40);

  return
}
